return Tour::query()->with(['location.city.country', 'categories'])->where(...)->get()->map(function (Tour $tour): array {
    $metadata = $this->sourceMetadata('tour', $tour->getKey());
    $classification = $this->tourExploreClassification($metadata['resource_type']);
    return ['id' => 'tour-' . $tour->getKey(), 'model_id' => $tour->getKey(), 'type' => $classification['type'], 'booking_type' => 'tour', 'label' => $classification['label'], 'name' => $tour->name, 'description' => $tour->description ?? $tour->short_description, 'latitude' => $this->nullableCoordinate($tour->location?->latitude), 'longitude' => $this->nullableCoordinate($tour->location?->longitude), 'has_coordinates' => $this->hasCoordinates($tour->location), 'address' => $this->address($tour->location), 'image' => $this->image($tour->main_image_url, 'tour'), 'rating' => $this->rating($tour->average_rating), 'base_price' => $this->money($tour->base_price), 'unit_price' => (float) ($tour->base_price ?? 0), 'phone' => null, 'email' => null, 'website' => null, 'featured' => (bool) $tour->is_featured, 'summary' => ['Duration' => $tour->duration_days ? $tour->duration_days . ' day(s)' : ($tour->duration_hours ? $tour->duration_hours . ' hour(s)' : 'Flexible'), 'Capacity' => $tour->max_capacity ? 'Up to ' . $tour->max_capacity : 'Flexible', 'From' => $this->money($tour->base_price)]] + $metadata;
})
